\set ON_ERROR_STOP on
BEGIN;
CREATE FUNCTION pg_temp.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'Assertion failed: %',msg; END IF; END $$;
CREATE FUNCTION pg_temp.must_fail(statement text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE rejected boolean:=false; BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN insufficient_privilege OR check_violation OR raise_exception OR foreign_key_violation OR unique_violation THEN rejected:=true; END;IF NOT rejected THEN RAISE EXCEPTION 'Expected rejection: %',statement; END IF;END $$;
CREATE TEMP TABLE x AS SELECT 'a0000000-0000-4000-8000-000000000001'::uuid firm,'a0000000-0000-4000-8000-000000000012'::uuid actor,'a0000000-0000-4000-8000-000000000015'::uuid student_user,'a0000000-0000-4000-8000-000000000013'::uuid parent,'a0000000-0000-4000-8000-000000000041'::uuid student,gen_random_uuid() college,gen_random_uuid() school,gen_random_uuid() app,NULL::uuid step,NULL::uuid task,NULL::uuid letter;
GRANT ALL ON x TO authenticated;
INSERT INTO colleges(id,name,slug) SELECT college,'Decision workspace test','decision-workspace-test' FROM x;
INSERT INTO student_colleges(id,firm_id,student_id,college_id,category,created_by_user_id,updated_by_user_id) SELECT school,firm,student,college,'target',actor,actor FROM x;
INSERT INTO applications(id,firm_id,student_id,student_college_id,college_id,application_type,stage,created_by_user_id,updated_by_user_id) SELECT app,firm,student,school,college,'rd','submitted',actor,actor FROM x;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_counselor"}',true);
SELECT public.record_application_decision(firm,actor,app,0,'deferred',current_date,NULL,false) FROM x;
SELECT pg_temp.assert((SELECT decision_result='deferred' AND decision_revision=1 FROM applications WHERE id=x.app),'current application updated') FROM x;
SELECT pg_temp.assert((SELECT decision_result='deferred' FROM student_colleges WHERE id=x.school),'college list updated') FROM x;
SELECT pg_temp.must_fail($q$SELECT public.record_application_decision(firm,actor,app,0,'accepted',current_date,NULL,false) FROM x$q$);
SELECT pg_temp.must_fail($q$SELECT public.record_application_decision(firm,actor,app,1,'accepted',current_date+2,NULL,false) FROM x$q$);
SELECT pg_temp.must_fail($q$UPDATE applications SET decision_result='accepted' WHERE id=(SELECT app FROM x)$q$);
SELECT pg_temp.must_fail($q$UPDATE student_colleges SET deposit_status='committed' WHERE id=(SELECT school FROM x)$q$);
SELECT public.initialize_decision_checklist(firm,actor,app,1) FROM x;
SELECT public.initialize_decision_checklist(firm,actor,app,1) FROM x;
SELECT pg_temp.assert((SELECT count(*)=3 FROM application_next_steps WHERE application_id=x.app),'suggested checklist is idempotent') FROM x;
UPDATE x SET step=(SELECT id FROM application_next_steps WHERE application_id=x.app AND template_key='letter');
UPDATE x SET letter=public.create_decision_letter(firm,actor,step,1);
SELECT pg_temp.assert(public.create_decision_letter(firm,actor,step,2)=letter,'letter creation does not duplicate writing') FROM x;
SELECT pg_temp.assert((SELECT visibility_scope='student' AND application_id=x.app FROM essay_drafts WHERE id=x.letter),'letter is ordinary student-visible application writing') FROM x;
-- Firm-visible writing is independently readable by the student and can be linked without changing its audience.
UPDATE essay_drafts SET visibility_scope='firm' WHERE id=(SELECT letter FROM x);
INSERT INTO application_next_steps(firm_id,student_id,application_id,decision_revision,kind,title,essay_id,created_by_user_id,updated_by_user_id)
 SELECT firm,student,app,1,'deferral','Review shared writing',letter,actor,actor FROM x;
UPDATE essay_drafts SET visibility_scope='student' WHERE id=(SELECT letter FROM x);
SELECT pg_temp.assert((SELECT application_phase='post_decision' FROM essay_drafts WHERE id=x.letter),'letter phase is separate') FROM x;
SELECT pg_temp.assert(jsonb_array_length(public.application_review_preview(firm,actor,app)->'manifest'->'essays')=0,'later letter does not change submission material') FROM x;
SELECT pg_temp.must_fail($q$UPDATE essay_drafts SET application_phase='application' WHERE id=(SELECT letter FROM x)$q$);
SELECT pg_temp.must_fail($q$UPDATE essay_drafts SET application_id=NULL,student_college_id=NULL WHERE id=(SELECT letter FROM x)$q$);
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_parent1"}',true);
SELECT pg_temp.assert((SELECT count(*)=1 FROM application_decision_events WHERE application_id=x.app),'family sees factual history') FROM x;
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM application_next_steps),'private next steps hidden');
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM essay_draft_versions WHERE essay_draft_id=x.letter),'private writing history stays hidden') FROM x;
SELECT pg_temp.must_fail($q$SELECT public.record_application_decision(firm,parent,app,1,'accepted',current_date,NULL,false) FROM x$q$);
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_student"}',true);
SELECT pg_temp.must_fail($q$SELECT public.record_application_decision(firm,student_user,app,1,'accepted',current_date,NULL,false) FROM x$q$);
UPDATE application_next_steps SET family_shared=true,revision=revision+1,updated_by_user_id=(SELECT student_user FROM x) WHERE id=(SELECT step FROM x);
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_counselor"}',true);
UPDATE x SET task=public.schedule_application_next_step(firm,actor,step,3,parent,current_date-1);
SELECT pg_temp.assert(public.schedule_application_next_step(firm,actor,step,3,parent,current_date-1)=task,'one open follow-up') FROM x;
SELECT pg_temp.must_fail($q$UPDATE tasks SET application_next_step_id=NULL WHERE id=(SELECT task FROM x)$q$);
SELECT pg_temp.must_fail($q$UPDATE tasks SET description='Unapproved content' WHERE id=(SELECT task FROM x)$q$);
SELECT pg_temp.must_fail($q$UPDATE tasks SET review_feedback='Private' WHERE id=(SELECT task FROM x)$q$);
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_parent2"}',true);
SELECT pg_temp.assert((SELECT count(*)=1 FROM application_next_steps),'both guardians see the approved step');
SELECT pg_temp.must_fail($q$SELECT public.transition_task(firm,'a0000000-0000-4000-8000-000000000014',task,'completed') FROM x$q$);
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_parent1"}',true);
SELECT public.transition_task(firm,parent,task,'completed') FROM x;
SELECT pg_temp.assert((SELECT status='needed' FROM application_next_steps WHERE id=x.step),'task completion is not college confirmation') FROM x;
SELECT public.transition_task(firm,parent,task,'pending') FROM x;
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_student"}',true);
UPDATE application_next_steps SET notes='Revised private planning',revision=revision+1,updated_by_user_id=(SELECT student_user FROM x) WHERE id=(SELECT step FROM x);
SELECT pg_temp.assert((SELECT visibility_scope='student' FROM tasks WHERE id=x.task),'derived task audience withdrawn') FROM x;
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_parent1"}',true);
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM tasks WHERE id=x.task),'parent task read withdrawn') FROM x;
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM notifications WHERE task_id=x.task),'parent notification feed withdrawn') FROM x;
RESET ROLE;
SELECT pg_temp.assert(NOT public.task_notice_allowed(task,parent),'queued service delivery withdrawn') FROM x;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_counselor"}',true);
SELECT public.record_application_decision(firm,actor,app,1,'waitlisted',current_date,NULL,false) FROM x;
SELECT pg_temp.assert((SELECT status='cancelled' FROM tasks WHERE id=x.task),'changed decision closes obsolete reminders') FROM x;
SELECT pg_temp.assert((SELECT count(*)=2 FROM application_decision_events WHERE application_id=x.app),'earlier deferred outcome preserved') FROM x;
SELECT pg_temp.must_fail($q$SELECT public.schedule_application_next_step(firm,actor,step,4,student_user,current_date) FROM x$q$);
SELECT public.record_application_decision(firm,actor,app,2,'accepted',current_date,'committed',false) FROM x;
SELECT public.initialize_decision_checklist(firm,actor,app,3) FROM x;
SELECT pg_temp.assert((SELECT count(*)=4 FROM application_next_steps WHERE application_id=x.app AND kind='enrollment'),'enrollment checklist created') FROM x;
SELECT pg_temp.assert((SELECT count(*)=3 FROM application_decision_events WHERE application_id=x.app),'full outcome sequence preserved') FROM x;
SELECT pg_temp.assert((SELECT deposit_status='committed' FROM student_colleges WHERE id=x.school),'enrollment synchronized') FROM x;
UPDATE x SET step=(SELECT id FROM application_next_steps WHERE application_id=x.app AND template_key='deposit');
UPDATE x SET task=public.schedule_application_next_step(firm,actor,step,1,student_user,current_date-1);
RESET ROLE;
SELECT public.enqueue_task_reminders();SELECT public.enqueue_task_reminders();
SELECT pg_temp.assert((SELECT count(*)=1 FROM notifications WHERE task_id=x.task AND kind='task_reminder'),'reminder deduplication retained') FROM x;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_alpha_student"}',true);
UPDATE application_next_steps SET status='completed',completed_on=current_date,revision=revision+1,updated_by_user_id=(SELECT student_user FROM x) WHERE id=(SELECT step FROM x);
SELECT pg_temp.assert((SELECT status='cancelled' FROM tasks WHERE id=x.task),'confirmed checklist completion closes reminders') FROM x;
SELECT set_config('request.jwt.claims','{"sub":"test_clerk_beta_owner"}',true);
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM application_decision_events),'cross-firm history hidden');
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM application_next_steps),'cross-firm steps hidden');
RESET ROLE;
SELECT pg_temp.must_fail($q$UPDATE application_decision_events SET result='rejected' WHERE application_id=(SELECT app FROM x)$q$);
SELECT pg_temp.must_fail($q$DELETE FROM application_decision_events WHERE application_id=(SELECT app FROM x)$q$);
UPDATE firm_memberships SET role='read_only_staff' WHERE firm_id=(SELECT firm FROM x) AND user_id=(SELECT actor FROM x);
SELECT pg_temp.must_fail($q$SELECT public.record_application_decision(firm,actor,app,3,'rejected',current_date,NULL,false) FROM x$q$);
SELECT pg_temp.must_fail($q$UPDATE application_next_steps SET notes='Read-only edit',revision=revision+1,updated_by_user_id=(SELECT actor FROM x) WHERE id=(SELECT step FROM x)$q$);
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM pg_proc WHERE proname IN ('next_step_current','guard_decision_event','guard_decision_projection','apply_decision_event','record_application_decision','guard_application_next_step','guard_next_step_task','sync_next_step_tasks','schedule_application_next_step','create_decision_letter','initialize_decision_checklist','guard_essay_application_phase') AND (prosecdef OR proconfig IS NULL OR has_function_privilege('anon',oid,'EXECUTE'))),'function security');
ROLLBACK;
